import React from 'react';
import '../styles/PlanningSection.css';

const PlanningSection = () => {
    return (
        <section className="planning-section">
            <div className="planning-container">
                <img src={`${process.env.PUBLIC_URL}/imgg/Rectangle 275.png`} alt="Планування" className="planning-bg" />
                <div className="planning-content">
                    <h2 className="planning-title">Сплануйте дизайн своєї кімнати онлайн</h2>
                    <div className="planning-divider"></div>
                    <p className="planning-description">
                        Вибирайте розміри, стиль, колір та фурнітуру. Дивіться, як все виглядає у 3D, та підганяйте під свій простір до міліметра.
                    </p>
                </div>
                <a href="#" className="planning-btn">Почати планування</a>
            </div>
        </section>
    );
};

export default PlanningSection;
